// Spaceline Tech — Cloudflare Worker
// Serves the shop, creates Stripe payments on the server, and hosts the Apple Pay domain file.
//
// Settings → Variables and Secrets (in the Cloudflare dashboard):
//   STRIPE_SECRET_KEY  (type: Secret)  your Stripe secret or restricted key, sk_live_... / rk_live_...
//   STRIPE_PK          (type: Text)    your Stripe publishable key, pk_live_...
//   DISCOUNT_CODES     (type: Text, optional)  e.g.  SAVE10:10,VIP20:20   (code:percent off items)
//
// Never paste your secret key anywhere else.

const PRICES = { one: 69900, pods: 12900, slate: 44900, pulse: 24900, boom: 7900, volt: 4900 };
const NAMES = { one: "Spaceline One", pods: "Pod Air", slate: "Slate 11", pulse: "Pulse Watch", boom: "Boom Mini", volt: "Volt 20K" };
const SHIPPING = { "Standard (3 to 5 days)": 799, "Express (1 to 2 days)": 1499, "Store pickup": 0 };
const TAX_RATE = 0.07;
const FREE_SHIPPING_FROM = 9900;

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });

function quote(body, env) {
  const items = body && body.items;
  if (!items || typeof items !== "object") throw new Error("Your cart is empty.");
  let sub = 0, count = 0;
  const lines = [];
  for (const [id, qRaw] of Object.entries(items)) {
    const q = Math.floor(Number(qRaw));
    if (!(id in PRICES)) throw new Error("Unknown product in cart.");
    if (!(q >= 1 && q <= 20)) throw new Error("Invalid quantity.");
    sub += PRICES[id] * q; count += q;
    lines.push(`${q} x ${NAMES[id]}`);
  }
  if (!count) throw new Error("Your cart is empty.");
  const codes = {};
  String(env.DISCOUNT_CODES || "").split(",").forEach(p => {
    const [c, pct] = p.split(":").map(x => (x || "").trim());
    if (c && +pct > 0 && +pct <= 90) codes[c.toUpperCase()] = +pct;
  });
  const asked = String(body.code || "").trim().toUpperCase().slice(0, 30);
  const pct = codes[asked] || 0;
  const disc = Math.round(sub * pct / 100);
  const after = sub - disc;
  const ship = String(body.ship || "");
  if (!(ship in SHIPPING)) throw new Error("Choose a delivery option.");
  const shipCost = ship === "Store pickup" ? 0 : (ship.startsWith("Standard") && after >= FREE_SHIPPING_FROM ? 0 : SHIPPING[ship]);
  const tax = Math.round(after * TAX_RATE);
  return { amount: after + shipCost + tax, code: pct ? asked : "", codeRejected: asked && !pct ? asked : "", lines, ship };
}

async function createPayment(body, env) {
  if (!env.STRIPE_SECRET_KEY) return json({ error: "Payments are not set up yet." }, 500);
  const num = String(body.num || "");
  if (!/^ST-\d{6}$/.test(num)) return json({ error: "Invalid order number." }, 400);
  const email = String(body.email || "").trim().slice(0, 200);
  if (!/^\S+@\S+\.\S+$/.test(email)) return json({ error: "Enter a valid email." }, 400);
  let q;
  try { q = quote(body, env); } catch (e) { return json({ error: e.message }, 400); }
  if (q.amount < 50) return json({ error: "Order total is too low." }, 400);
  const clip = v => String(v || "").slice(0, 450);
  const form = new URLSearchParams();
  form.set("amount", String(q.amount));
  form.set("currency", "usd");
  form.set("automatic_payment_methods[enabled]", "true"); form.set("automatic_payment_methods[allow_redirects]", "never");
  form.set("receipt_email", email);
  form.set("description", `Spaceline Tech order ${num}`);
  form.set("metadata[order]", num);
  form.set("metadata[name]", clip(body.name));
  form.set("metadata[email]", email);
  form.set("metadata[phone]", clip(body.phone));
  form.set("metadata[address]", clip(body.addr));
  form.set("metadata[delivery]", q.ship);
  form.set("metadata[items]", clip(q.lines.join(", ")));
  if (q.code) form.set("metadata[discount_code]", q.code);
  const r = await fetch("https://api.stripe.com/v1/payment_intents", {
    method: "POST",
    headers: {
      authorization: "Bearer " + env.STRIPE_SECRET_KEY,
      "content-type": "application/x-www-form-urlencoded",
      "idempotency-key": `${num}-${q.amount}`
    },
    body: form
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok || !d.client_secret) return json({ error: (d.error && d.error.message) || "Stripe could not start the payment." }, 502);
  return json({ clientSecret: d.client_secret, amount: q.amount, code: q.code, codeRejected: q.codeRejected });
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (url.pathname === "/.well-known/apple-developer-merchantid-domain-association") {
      const r = await fetch("https://stripe.com/files/apple-pay/apple-developer-merchantid-domain-association");
      return new Response(r.body, { status: r.status, headers: { "content-type": "text/plain" } });
    }
    if (url.pathname === "/api/pay") {
      if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);
      let body;
      try { body = await req.json(); } catch { return json({ error: "Bad request" }, 400); }
      return createPayment(body, env);
    }
    if (url.pathname === "/" || url.pathname === "/index.html") {
      const pk = /^pk_(live|test)_[A-Za-z0-9]+$/.test(env.STRIPE_PK || "") ? env.STRIPE_PK : "";
      return new Response(HTML.replace("__STRIPE_PK__", pk), {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-content-type-options": "nosniff", "referrer-policy": "strict-origin-when-cross-origin" }
      });
    }
    return new Response("Not found", { status: 404 });
  }
};

